package vn.edu.studymate;
import static org.junit.Assert.*;
import android.app.*;import android.content.*;import android.os.*;import android.service.notification.StatusBarNotification;
import androidx.test.platform.app.InstrumentationRegistry;
import org.junit.*;import java.util.*;
import vn.edu.studymate.auth.Session;import vn.edu.studymate.data.DatabaseHelper;import vn.edu.studymate.model.Entry;import vn.edu.studymate.reminder.ReminderScheduler;import vn.edu.studymate.ui.EditorActivity;
public class EnvironmentLifecycleTest {
 Instrumentation ins=InstrumentationRegistry.getInstrumentation();Context c=ins.getTargetContext();DatabaseHelper db;long user;
 @Before public void setup() throws Exception {if(Build.VERSION.SDK_INT>=33){ins.getUiAutomation().executeShellCommand("pm grant "+c.getPackageName()+" android.permission.POST_NOTIFICATIONS").close();Thread.sleep(300);}Session.logout(c);db=new DatabaseHelper(c);user=db.register("Lifecycle","lifecycle"+System.nanoTime()+"@test.vn","Test123!");Session.login(c,user);}
 @After public void cleanup(){Session.logout(c);db.getWritableDatabase().delete("users","id=?",new String[]{""+user});db.close();}
 Entry task(){Entry e=new Entry();e.kind="task";e.title="Nhiệm vụ kiểm thử";e.dueAt=System.currentTimeMillis()+1800000;e.minutesBefore=60;db.save(user,e);return e;}
 NotificationManager manager(){return (NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);}
 @Test public void AD04EditedDeletedAndCompletedTargetsCannotLeaveStaleNotifications(){Entry e=task();ReminderScheduler.check(c);assertEquals(1,manager().getActiveNotifications().length);e.dueAt+=86400000;db.save(user,e);ReminderScheduler.check(c);assertEquals(0,manager().getActiveNotifications().length);e.dueAt=System.currentTimeMillis()+1800000;db.save(user,e);e.status="Hoàn thành";db.save(user,e);ReminderScheduler.check(c);assertEquals(0,manager().getActiveNotifications().length);e.status="Chưa làm";db.save(user,e);db.delete(user,e.id);ReminderScheduler.check(c);assertEquals(0,manager().getActiveNotifications().length);}
 @Test public void AD08OldNotificationCannotOpenAnotherAccountsData() throws Exception {Entry e=task();ReminderScheduler.check(c);StatusBarNotification[] all=manager().getActiveNotifications();assertEquals(1,all.length);PendingIntent stale=all[0].getNotification().contentIntent;Session.logout(c);long other=db.register("Other","otherlife"+System.nanoTime()+"@test.vn","Test123!");Session.login(c,other);Instrumentation.ActivityMonitor monitor=ins.addMonitor(EditorActivity.class.getName(),null,false);try{stale.send();Activity attempted=ins.waitForMonitorWithTimeout(monitor,5000);assertNotNull(attempted);ins.waitForIdleSync();assertTrue(attempted.isFinishing()||attempted.isDestroyed());assertNull(db.get(other,e.id));assertEquals(other,Session.user(c));assertEquals(0,manager().getActiveNotifications().length);}finally{ins.removeMonitor(monitor);db.getWritableDatabase().delete("users","id=?",new String[]{""+other});}}
 @Test public void independentRemindersPostOnceAndKeepTheirOwnTimestamp(){Entry e=task();e.minutesBefore=60;e.reminderOffsets=Arrays.asList(30,1440);db.save(user,e);ReminderScheduler.check(c);List<Entry> reminders=db.scheduledReminders(user);assertEquals(3,reminders.size());for(Entry r:reminders)assertEquals(e.dueAt,r.handledAt);long revision=db.reminderRevision(user);ReminderScheduler.check(c);assertEquals(revision,db.reminderRevision(user));}
}
